export const BODY: string = "\n<p>واٹر مارک تصویر پر لگایا گیا وہ نشان ہے جو بتاتا ہے کہ تصویر کس کی ہے۔ یہ نام، لوگو یا ویب سائٹ کا پتہ ہو سکتا ہے، اور یہ تصویر کی حفاظت اور پہچان، دونوں کا کام کرتا ہے۔</p>\n<p>اچھا واٹر مارک نظر آتا ہے مگر تصویر کو خراب نہیں کرتا۔ برا واٹر مارک یا تو اتنا ہلکا ہوتا ہے کہ کوئی دیکھتا ہی نہیں، یا اتنا بھاری کہ تصویر دیکھنے کے قابل نہیں رہتی۔</p>\n<p>یہ رہنما متن اور لوگو کے نشان، ٹائل والا نمونہ، شفافیت، جگہ، سائز، رنگ اور عام غلطیوں کی وضاحت کرتا ہے۔ نشان لگانے کے لیے <a href=\"/ur/tasveer-par-watermark-lagayein/\">امیج واٹر مارک</a> کھولیں۔</p>\n<h2 id=\"what-is-a-watermark\">واٹر مارک کیا ہے؟</h2>\n<p>واٹر مارک تصویر کے اوپر لگایا گیا شفاف نشان ہے، جو تصویر کے مالک کی پہچان ظاہر کرتا ہے۔ یہ اکثر کونے میں یا تصویر کے بیچ میں ہلکا سا نظر آتا ہے۔</p>\n<p>واٹر مارک کا مقصد چوری روکنا اور برانڈنگ کرنا ہے۔ اگر کوئی تصویر بغیر اجازت استعمال کرے تو نشان سے پتا چل جاتا ہے کہ وہ کس کی ہے۔</p>\n<p>واٹر مارک تصویر کا حصہ بن جاتا ہے، اس لیے اسے ہٹانا مشکل ہوتا ہے۔ یہی اس کی طاقت ہے، اور یہی اس کی کمزوری بھی، کیونکہ غلط نشان تصویر کو ہمیشہ کے لیے خراب کر دیتا ہے۔</p>\n<h2 id=\"text-vs-logo-watermarks\">متن والے نشان بمقابلہ لوگو والے نشان</h2>\n<p>متن والا نشان آپ کا نام یا ویب سائٹ لکھتا ہے، جو پڑھنے میں آسان اور بنانے میں سستا ہے۔ یہ فوٹوگرافروں کے لیے بہترین ہے، جن کا نام ہی ان کی پہچان ہے۔</p>\n<p>لوگو والا نشان آپ کی برانڈ کی تصویر ہوتا ہے، جو زیادہ پیشہ ورانہ لگتا ہے۔ لیکن لوگو بنانا وقت لیتا ہے، اور چھوٹے سائز میں لوگو پہچانا نہیں جاتا۔</p>\n<p>شروعات میں متن والا نشان کافی ہے۔ جب برانڈ مضبوط ہو جائے تو لوگو والا نشان اپنائیں، تاکہ ہر تصویر پر ایک ہی پہچان نظر آئے۔</p>\n<h2 id=\"tiled-repeat-pattern\">ٹائل والا دہرایا جانے والا نمونہ</h2>\n<p>ٹائل والا نمونہ نشان کو پوری تصویر پر بار بار دہراتا ہے، جیسے دیوار پر ٹائل۔ اس سے تصویر کا کوئی بھی حصہ کاٹ کر نشان سے بچا نہیں جا سکتا۔</p>\n<p>یہ نمونہ کلائنٹ کے ثبوت اور اسٹاک تصویروں کے لیے بہترین ہے، کیونکہ یہ تصویر کو محفوظ رکھتا ہے۔ لیکن یہ تصویر دیکھنے میں رکاوٹ بھی بنتا ہے، اس لیے اسے بہت ہلکا رکھیں۔</p>\n<p>ٹائل والا نشان صرف اس وقت استعمال کریں جب حفاظت سب سے اہم ہو۔ عام سوشل پوسٹ پر یہ نشان تصویر کو خراب کر دیتا ہے۔</p>\n<h2 id=\"opacity-and-visibility\">شفافیت: حفاظت کے لیے کافی نظر آنے والا، دیکھنے کے لیے کافی ہلکا</h2>\n<p>شفافیت طے کرتی ہے کہ نشان کتنا نظر آئے گا۔ 30 سے 50 فیصد شفافیت اکثر بہترین توازن ہے: نشان نظر آتا ہے، مگر تصویر کے پیچھے نہیں چھپتا۔</p>\n<p>بہت ہلکا نشان بیکار ہے، کیونکہ اسے ہٹانا آسان ہے اور کوئی دیکھتا ہی نہیں۔ بہت بھاری نشان تصویر کو خراب کر دیتا ہے اور دیکھنے والا پریشان ہوتا ہے۔</p>\n<p>شفافیت کو تصویر کے پس منظر سے ملائیں: ہلکے پس منظر پر گہرا نشان اور گہرے پس منظر پر ہلکا نشان زیادہ نظر آتا ہے۔</p>\n<h2 id=\"placement-strategy\">نشان کہاں لگائیں</h2>\n<p>کونے میں لگایا گیا نشان سب سے عام ہے، کیونکہ وہ تصویر کو کم متاثر کرتا ہے۔ لیکن کونے کا نشان کاٹ کر ہٹانا بھی سب سے آسان ہے۔</p>\n<p>بیچ میں لگایا گیا نشان ہٹانا مشکل ہے، مگر وہ تصویر کا مرکزی حصہ ڈھانپ لیتا ہے۔ درمیانہ حل یہ ہے کہ نشان کو اہم موضوع کے قریب، مگر اس کے اوپر نہیں، لگائیں۔</p>\n<p>جگہ چنتے وقت یہ سوچیں کہ چور تصویر کو کیسے استعمال کرے گا۔ اگر وہ تصویر کاٹ سکتا ہے تو نشان بیچ کے قریب لگائیں، ورنہ کونہ کافی ہے۔</p>\n<h2 id=\"text-size-and-scaling\">متن کا سائز: چھوٹی تصویروں بمقابلہ بڑی تصویروں</h2>\n<p>نشان کا سائز تصویر کے سائز سے ملنا چاہیے۔ چھوٹی تصویر پر بڑا نشان تصویر کو ڈھانپ لیتا ہے، جبکہ بڑی تصویر پر چھوٹا نشان نظر ہی نہیں آتا۔</p>\n<p>اصول یہ ہے کہ نشان تصویر کی چوڑائی کا تقریباً دس فیصد ہو۔ اس سے وہ پڑھنے کے قابل رہتا ہے، بغیر تصویر پر حاوی ہوئے۔</p>\n<p>بیچ میں کئی سائز کی تصویریں ہوں تو ہر ایک کے لیے سائز الگ طے کریں۔ ایک ہی سائز سب پر لگانے سے چھوٹی تصویریں خراب ہو جاتی ہیں۔</p>\n<h2 id=\"watermark-colour-and-contrast\">رنگ اور تضاد: نشان کو ہر پس منظر پر پڑھنے کے قابل بنانا</h2>\n<p>سفید نشان ہلکے پس منظر پر غائب ہو جاتا ہے، اور کالا نشان گہرے پس منظر پر۔ اس لیے نشان کا رنگ پس منظر کے مخالف ہونا چاہیے۔</p>\n<p>بہترین حل یہ ہے کہ نشان کے گرد ہلکا سایہ یا خاکہ لگائیں، جس سے وہ ہر پس منظر پر نظر آئے۔ سفید نشان پر کالا خاکہ ہر جگہ پڑھا جا سکتا ہے۔</p>\n<p>رنگ چنتے وقت برانڈ کا رنگ بھی دیکھیں، مگر پڑھنے کی اہلیت پہلے آتی ہے۔ اگر برانڈ کا رنگ پس منظر میں گم ہو جائے تو سایہ لگا کر اسے نمایاں کریں۔</p>\n<h2 id=\"rotation-and-angle\">گھماؤ اور زاویہ</h2>\n<p>ترچھا نشان، جیسے 45 درجے پر، تصویر پر کم جگہ لیتا ہے اور زیادہ علاقہ ڈھانپتا ہے۔ یہ کلائنٹ کے ثبوت کے لیے اچھا ہے، کیونکہ اسے ہٹانا مشکل ہے۔</p>\n<p>لیکن ترچھا متن پڑھنا مشکل ہوتا ہے، اس لیے برانڈنگ کے لیے سیدھا نشان بہتر ہے۔ زاویہ صرف اس وقت استعمال کریں جب حفاظت پڑھنے سے زیادہ اہم ہو۔</p>\n<p>زاویہ ہلکا رکھیں، جیسے 15 سے 30 درجے۔ بہت ترچھا نشان تصویر کو بے ترتیب بنا دیتا ہے۔</p>\n<h2 id=\"formats-and-transparency\">فارمیٹ، شفافیت اور برآمد</h2>\n<p>لوگو کے لیے PNG استعمال کریں، کیونکہ اس میں شفافیت بچتی ہے۔ JPG لوگو کا پس منظر سفید کر دیتا ہے، جو تصویر پر عجیب لگتا ہے۔</p>\n<p>نشان لگی تصویر کو اسی فارمیٹ میں محفوظ کریں جس میں اصل تھی، تاکہ معیار نہ بدلے۔ برآمد سے پہلے نشان کو مکمل سائز میں دیکھیں۔</p>\n<p>اصل فائل بغیر نشان کے محفوظ رکھیں، تاکہ بعد میں نشان بدلا جا سکے۔ نشان لگی فائل سے نشان ہٹانا تقریباً ناممکن ہے۔</p>\n<h2 id=\"watermark-vs-copyright\">واٹر مارک اور کاپی رائٹ: نشان کیا کر سکتا ہے اور کیا نہیں</h2>\n<p>واٹر مارک ملکیت کا ثبوت دیتا ہے، مگر قانونی کاپی رائٹ کی جگہ نہیں لیتا۔ کاپی رائٹ قانون سے ملتا ہے، نشان صرف اسے ظاہر کرتا ہے۔</p>\n<p>نشان چوری کو مشکل بناتا ہے، مگر ناممکن نہیں۔ ماہر ایڈیٹر نشان ہٹا سکتا ہے، اس لیے اہم کام کے لیے قانونی تحفظ بھی ضروری ہے۔</p>\n<p>نشان کو کاپی رائٹ کی علامت سمجھیں، نہ کہ قانونی تحفظ۔ یہ لوگوں کو خبردار کرتا ہے، مگر عدالت میں ثبوت کے لیے اصل فائل اور تاریخ بھی چاہیے۔</p>\n<h2 id=\"privacy-and-local-processing\">پرائیویسی: بغیر اپ لوڈ کے نشان لگانا</h2>\n<p>نشان لگانا آپ کے براؤزر میں ہوتا ہے، تصویر کسی سرور پر نہیں جاتی۔ یہ کلائنٹ کی نجی تصویروں کے لیے بہت اہم ہے، کیونکہ فائل آپ کے آلے سے باہر نہیں نکلتی۔</p>\n<p>براؤزر بند کرنے پر ڈیٹا ختم ہو جاتا ہے۔ کوئی اکاؤنٹ نہیں بنتا اور کوئی نقل محفوظ نہیں رہتی، اس لیے کلائنٹ کی تصویریں بے فکر ہو کر نشان زد کریں۔</p>\n<p>لیکن نشان لگی تصویر شیئر کرنے کا مطلب ہے کہ نشان میں لکھا نام یا ویب سائٹ سب کو نظر آئے گا۔ نشان لگانے سے پہلے متن جانچ لیں۔</p>\n<h2 id=\"common-watermark-mistakes\">عام واٹر مارک غلطیاں</h2>\n<p>سب سے عام غلطی نشان کو بہت بڑا یا بہت بھاری بنانا ہے، جس سے تصویر دیکھنے کے قابل نہیں رہتی۔ دوسری غلطی نشان کو کونے میں اتنا چھوٹا لگانا ہے کہ کوئی دیکھتا ہی نہیں۔</p>\n<p>تیسری غلطی ہر تصویر پر الگ نشان لگانا ہے، جس سے برانڈ کی پہچان نہیں بنتی۔ ایک ہی نشان، ایک ہی جگہ اور ایک ہی سائز رکھیں۔</p>\n<p>چوتھی غلطی اصل فائل پر ہی نشان لگا کر محفوظ کر دینا ہے۔ ہمیشہ نقل پر نشان لگائیں اور اصل کو بغیر نشان کے رکھیں۔</p>\n<h2 id=\"watermark-workflow\">کلائنٹ کے ثبوت کے لیے نشان کا طریقہ</h2>\n<p>کلائنٹ کو ثبوت بھیجتے وقت تصویر پر ٹائل والا ہلکا نشان لگائیں، تاکہ وہ تصویر استعمال نہ کر سکے۔ ادائیگی کے بعد بغیر نشان والی اصل فائل بھیجیں۔</p>\n<p>ثبوت والی فائل کا نام بھی واضح رکھیں، جیسے proof یا preview، تاکہ کلائنٹ کو معلوم ہو کہ یہ حتمی فائل نہیں ہے۔</p>\n<p>ثبوت بھیجنے سے پہلے خود تصویر دیکھیں: کیا نشان پڑھا جا سکتا ہے، کیا تصویر سمجھ آتی ہے، اور کیا اصل فائل محفوظ ہے۔</p>\n<h2 id=\"watermarking-social-media\">سوشل میڈیا کے لیے نشان لگانا</h2>\n<p>سوشل میڈیا پر نشان ہلکا اور چھوٹا ہونا چاہیے، کیونکہ لوگ تصویر دیکھنے آتے ہیں، نشان دیکھنے نہیں۔ کونے میں چھوٹا نام یا لوگو کافی ہے۔</p>\n<p>سوشل میڈیا پر تصویر اکثر دوبارہ شیئر ہوتی ہے، اور نشان ہی بتاتا ہے کہ وہ کس کی ہے۔ اس لیے نشان اتنا واضح ہو کہ شیئر ہونے پر بھی پہچانا جائے۔</p>\n<p>لیکن نشان اتنا بڑا نہ ہو کہ لوگ تصویر شیئر کرنا چھوڑ دیں۔ توازن ہی سوشل میڈیا کی کامیابی ہے۔</p>\n<h2 id=\"watermarking-stock-photos\">اسٹاک اور پیش نظارہ تصویروں پر نشان</h2>\n<p>اسٹاک تصویروں کے پیش نظارہ پر ٹائل والا نشان لگایا جاتا ہے، تاکہ کوئی مفت میں استعمال نہ کر سکے۔ خریدنے کے بعد بغیر نشان والی فائل ملتی ہے۔</p>\n<p>پیش نظارہ کا نشان اتنا ہلکا ہو کہ خریدار تصویر دیکھ سکے، مگر اتنا واضح ہو کہ وہ اسے استعمال نہ کر سکے۔ یہی توازن اسٹاک کاروبار کی بنیاد ہے۔</p>\n<p>پیش نظارہ کی تصویر کا سائز بھی چھوٹا رکھیں، تاکہ وہ پرنٹ یا بڑی اسکرین پر استعمال نہ ہو سکے۔</p>\n<h2 id=\"watermark-removal-myths\">نشان ہٹانے کے بارے میں غلط فہمیاں</h2>\n<p>ایک غلط فہمی یہ ہے کہ نشان کو کبھی ہٹایا نہیں جا سکتا۔ حقیقت یہ ہے کہ ماہر ایڈیٹر نشان ہٹا سکتا ہے، خاص طور پر اگر نشان ہلکا اور کونے میں ہو۔</p>\n<p>دوسری غلط فہمی یہ ہے کہ نشان ہٹانے والا ٹول ہر نشان ہٹا دیتا ہے۔ ٹول صرف سادہ نشان ہٹاتا ہے، ٹائل والا یا بیچ میں لگا نشان اکثر باقی رہ جاتا ہے۔</p>\n<p>نشان کو مکمل تحفظ نہ سمجھیں: یہ رکاوٹ ہے، دیوار نہیں۔ اہم کام کے لیے قانونی تحفظ بھی ضروری ہے۔</p>\n<h2 id=\"watermarking-and-branding\">برانڈنگ کے طور پر نشان لگانا</h2>\n<p>نشان آپ کے برانڈ کی دستخط ہے: ہر تصویر پر ایک ہی نشان دیکھ کر لوگ آپ کو پہچاننے لگتے ہیں۔ مستقل نشان برانڈ کی پہچان بناتا ہے۔</p>\n<p>برانڈنگ کے لیے نشان کو سادہ اور پڑھنے کے قابل رکھیں۔ پیچیدہ لوگو چھوٹے سائز میں پہچانا نہیں جاتا، جبکہ سادہ نام ہر جگہ کام کرتا ہے۔</p>\n<p>نشان میں ویب سائٹ کا پتہ بھی شامل کریں، تاکہ تصویر دیکھنے والا آپ تک پہنچ سکے۔ نشان لگانے کے بہترین طریقے <a href=\"/ur/blog/watermark-behtareen-tareeqe/\">واٹر مارک کے بہترین طریقے</a> میں اور عملی مراحل <a href=\"/ur/blog/tasveer-par-watermark-kaise-lagayein/\">تصویر پر واٹر مارک کیسے لگائیں</a> میں دیکھیں۔ متن شامل کرنا ہو تو <a href=\"/ur/tasveer-par-text-likhein/\">تصویر پر متن شامل کریں</a>۔</p>\n";

